import{_ as n,o as a,c as e,a2 as p}from"./chunks/framework.DZO5kRrk.js";const h=JSON.parse('{"title":"DeepAgents 框架概览与设计理念","description":"","frontmatter":{},"headers":[],"relativePath":"docs/ai/18-deep-agents-overview.md","filePath":"docs/ai/18-deep-agents-overview.md"}'),t={name:"docs/ai/18-deep-agents-overview.md"};function o(l,s,i,c,r,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="deepagents-框架概览与设计理念" tabindex="-1">DeepAgents 框架概览与设计理念 <a class="header-anchor" href="#deepagents-框架概览与设计理念" aria-label="Permalink to &quot;DeepAgents 框架概览与设计理念&quot;">​</a></h1><p><img src="https://api.cheatppf.xyz/i/2go5iatp59c-xb7qrb.png" alt="image"><code>deep_agents</code> 是一个专为构建生产级、多智能体（Multi-Agent）与有状态 AI 工作流打造的 Python 核心 SDK。它完全对标 TypeScript 生态的 <code>deepagents</code> 框架，为 Python 开发者提供了开箱即用的高并发任务委派、虚拟沙箱、SOP 技能注入、长期记忆持久化、结构化任务跟踪与防溢出上下文裁剪能力。</p><hr><h2 id="核心设计哲学" tabindex="-1">核心设计哲学 <a class="header-anchor" href="#核心设计哲学" aria-label="Permalink to &quot;核心设计哲学&quot;">​</a></h2><p>传统的 Agent 框架（如简单 Prompt + ReAct）在面对复杂多步骤任务时，常面临以下四大痛点：</p><ol><li><strong>Token 溢出与历史崩溃</strong>：对话工具调用过多导致 Context Exceeded。</li><li><strong>缺乏状态可追踪性</strong>：外部程序无法获取 Agent 当前处理到第几步。</li><li><strong>权限与越权风控</strong>：Agent 自由读写本地任意磁盘文件带来安全隐患。</li><li><strong>串行阻塞低效</strong>：主 Agent 一个一个委派子 Agent，效率极低。</li></ol><p><code>deep_agents</code> 框架通过**“底层图引擎 + 插件化中间件 + 高并发调度器”**的三层解耦架构彻底解决了上述问题。</p><hr><h2 id="整体架构视图" tabindex="-1">整体架构视图 <a class="header-anchor" href="#整体架构视图" aria-label="Permalink to &quot;整体架构视图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------------------------------+</span></span>
<span class="line"><span>|                    DeepAgents 应用层 (如 Deep Research)                 |</span></span>
<span class="line"><span>+-----------------------------------------------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>                                  v</span></span>
<span class="line"><span>+-----------------------------------------------------------------------+</span></span>
<span class="line"><span>|                       DeepAgents Core 引擎                            |</span></span>
<span class="line"><span>|  - create_agent (ReAct 思考图 + 自动防溢出 + 两阶段格式化)              |</span></span>
<span class="line"><span>|  - create_subagent_tools (单步委派 + asyncio.gather 高并发并行调度)    |</span></span>
<span class="line"><span>+-----------------------------------------------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>        +-------------------------+-------------------------+</span></span>
<span class="line"><span>        |                                                   |</span></span>
<span class="line"><span>        v                                                   v</span></span>
<span class="line"><span>+------------------------------------+    +------------------------------------+</span></span>
<span class="line"><span>|       Middlewares 中间件插件库       |    |          Tools 基础工具库          |</span></span>
<span class="line"><span>|  - fs: 虚拟沙箱与 RBAC 权限控制    |    |  - python_repl: REPL 代码沙箱      |</span></span>
<span class="line"><span>|  - skills: SOP 技能动态注入器       |    |  - web_search: 博查搜索引擎       |</span></span>
<span class="line"><span>|  - memory: AGENTS.md 长期记忆持久化 |    +------------------------------------+</span></span>
<span class="line"><span>|  - todo: 结构化 Task 拆解与追踪器   |</span></span>
<span class="line"><span>|  - context: 智能上下文滑动窗裁切    |</span></span>
<span class="line"><span>|  - logger: 全链路 Trace 结构化日志  |</span></span>
<span class="line"><span>+------------------------------------+</span></span></code></pre></div><hr><h2 id="六大核心特性亮点" tabindex="-1">六大核心特性亮点 <a class="header-anchor" href="#六大核心特性亮点" aria-label="Permalink to &quot;六大核心特性亮点&quot;">​</a></h2><ol><li><p>⚡ <strong>高并发 Map-Reduce 调度</strong> 内置 <code>delegate_tasks_parallel</code> 调度器，底层基于 Python 原生 <code>asyncio.gather</code>，支持主 Agent 在单次思考中并行拉起多个调研员子 Agent，效率提升 60%+。</p></li><li><p>🛡️ <strong>虚拟沙箱与 RBAC 权限策略</strong> 绝对隔离真实物理文件系统。支持针对不同的 Agent 配置 <code>read</code> / <code>write</code> / <code>deny</code> 细粒度权限白名单，防止越权写入或穿越。</p></li><li><p>📚 <strong>SOP 技能库动态加载</strong> 自动解析 <code>.agents/skills/</code> 目录下的 Markdown 技能指南，生成标准 XML 元数据并注入 System Prompt。主 Agent 仅在需要时按需调用工具读取 SOP 指南。</p></li><li><p>🧠 <strong><code>AGENTS.md</code> 长期记忆</strong> 自动在会话启动时恢复 <code>/AGENTS.md</code> 记忆文件，并指导 Agent 在收到用户“请记住...”指令时，使用沙箱工具增量更新记忆。</p></li><li><p>📋 <strong>结构化 Task 进度暴露</strong> 彻底告别纯文本 Prompt 的虚假步骤。提供闭包 API <code>get_todos()</code>，随时向 UI 前端暴露标准的 <code>[{content, status}]</code> 任务进度状态。</p></li><li><p>✂️ <strong>智能上下文滑窗裁切</strong> 在 ReAct 思考循环中自动识别并保护顶部系统 Prompt、技能书与记忆，仅滑动裁切过长历史对话，彻底告别 Token 溢出报错。</p></li></ol>`,13)])])}const _=n(t,[["render",o]]);export{h as __pageData,_ as default};
